namespace {
void require(bool condition,const QString &message){if(!condition)throw std::runtime_error(message.toUtf8().constData());}
void spin(int ms){QElapsedTimer timer;timer.start();while(timer.elapsed()<ms){QCoreApplication::processEvents(QEventLoop::AllEvents,10);QThread::msleep(5);}}
QImage legacyLevels(const QImage &input,const Adjustments &a){
    QImage image=input.copy();
    for(int y=0;y<image.height();++y){auto *line=(QRgb*)image.scanLine(y);for(int x=0;x<image.width();++x){QColor c=QColor::fromRgba(line[x]);float h,s,v;c.getHsvF(&h,&s,&v);h=float(std::fmod(std::max(0.f,h)+a.hue/360.+1,1));c.setHsvF(h,float(std::clamp(s*a.saturation,0.,1.)),float(std::clamp(v+a.brightness,0.,1.)),c.alphaF());auto level=[&](double n,double balance){return qRound(std::clamp(std::pow(std::clamp((n-a.blacks)/std::max(.001,a.whites-a.blacks),0.,1.),1/a.gamma)+balance,0.,1.)*255);};line[x]=qRgba(level(c.redF(),a.red),level(c.greenF(),a.green),level(c.blueF(),a.blue),c.alpha());}}
    return image;
}
}
