        const QString blenderObj="C:/Users/rmart/Reign of Glory/Character Creator 4/base/caleb model_base_xxx.obj";if(QFileInfo::exists(blenderObj)){ModelAsset blenderAsset;QString blenderError;require(ModelImporter::load(blenderObj,blenderAsset,blenderError),blenderError);require(!blenderAsset.vertices.isEmpty()&&!blenderAsset.triangles.isEmpty(),"Blender OBJ mesh extraction failed");report<<QString("PASS: Blender OBJ mesh import · %1 triangles").arg(blenderAsset.triangles.size());}
        const QString blenderFbx="C:/Users/rmart/Reign of Glory/blender/fence/fbx/reign of glory - door hinge.fbx";if(QFileInfo::exists(blenderFbx)){ModelAsset blenderFbxAsset;QString blenderFbxError;require(ModelImporter::load(blenderFbx,blenderFbxAsset,blenderFbxError),blenderFbxError);require(!blenderFbxAsset.vertices.isEmpty()&&!blenderFbxAsset.triangles.isEmpty(),"Blender FBX mesh extraction failed");report<<QString("PASS: Blender binary FBX mesh import · %1 vertices · %2 triangles · %3 materials").arg(blenderFbxAsset.vertices.size()).arg(blenderFbxAsset.triangles.size()).arg(blenderFbxAsset.materials.size());}
